#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):6;unsigned long long maxm=1ULL<<(n*(n-1)/2);map<array<long long,8>,pair<vector<int>,int>> bank;for(unsigned long long mask=0;mask<maxm;mask++){vector<int>a(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++)if(mask>>k&1)a[i]|=1<<j;else a[j]|=1<<i;int N=1<<n;vector<long long>H(N);vector<vector<long long>>E(N,vector<long long>(n)),S=E;H[0]=1;for(int v=0;v<n;v++)E[1<<v][v]=S[1<<v][v]=1;for(int m=1;m<N;m++){for(int v=0;v<n;v++)if(m>>v&1){int r=m^(1<<v);if(r)for(int u=0;u<n;u++)if(r>>u&1){if(a[u]>>v&1)E[m][v]+=E[r][u];if(a[v]>>u&1)S[m][v]+=S[r][u];}H[m]+=E[m][v];}}for(int b=0;b<n;b++){long long L=0,R=0,B=0;int full=N-1,del=full^(1<<b);for(int u=0;u<N;u++){if(u>>b&1){L+=E[u][b]*H[full^u];R+=S[u][b]*H[full^u];}if((u&del)==u)B+=H[u]*H[del^u];}array<long long,8> sig={H[full],S[full][b],L,E[full][b],R,B,(n==1),H[del]};bank.emplace(sig,make_pair(a,b));}}cout<<"[\n";bool first=true;for(auto &[sig,val]:bank){if(!first)cout<<",\n";first=false;cout<<"{\"signature\":[";for(int i=0;i<7;i++){if(i)cout<<",";cout<<sig[i];}cout<<"],\"H_deleted_root\":"<<sig[7]<<",\"root\":"<<val.second<<",\"rows\":[";for(int i=0;i<n;i++){if(i)cout<<",";cout<<val.first[i];}cout<<"]}";}cout<<"\n]\n";cerr<<"order "<<n<<" graphs "<<maxm<<" matrices "<<bank.size()<<"\n";}
